// Sjednotí vstup ze dvou spouštěčů (chat widget / HTTP webhook)
// do jednoho tvaru { dotaz, session_id, kanal }, se kterým dál pracuje agent.
const vystup = [];

for (const item of $input.all()) {
  const j = item.json;

  // Chat trigger posílá chatInput + sessionId, webhook má data v body.
  const jeChat = j.chatInput !== undefined;
  const body = j.body ?? {};

  const dotaz = jeChat ? j.chatInput : (body.dotaz ?? body.question ?? body.chatInput ?? '');
  if (!dotaz) {
    throw new Error("Chybí dotaz. Webhook očekává JSON { \"dotaz\": \"...\" }.");
  }

  vystup.push({
    json: {
      dotaz: String(dotaz),
      session_id: String(jeChat ? (j.sessionId ?? 'chat') : (body.session_id ?? 'webhook')),
      kanal: jeChat ? 'chat' : 'webhook',
    },
  });
}

return vystup;

